import Foundation

/// Built-in New York subway station catalog.
///
/// Generated by `tools/generate_stations.py` from MTA's official static GTFS and the "MTA Subway Stations" table,
/// including each station's GTFS ID, name, coordinates, stop group, signage direction names,
/// and the most common terminal in both directions for each route. Station names use MTA's official English names.
public struct StationCatalog: Sendable {

    public struct RouteDirections: Codable, Hashable, Sendable {
        public var route: String
        /// Terminal northbound (platform ID suffix N)
        public var north: String?
        /// Terminal southbound (platform ID suffix S)
        public var south: String?
    }

    public struct Entry: Codable, Hashable, Sendable, Identifiable {
        public var id: String
        public var name: String
        public var lat: Double
        public var lon: Double
        public var routes: [RouteDirections]
        /// MTA stop group ID (stations with in-station transfers share one)
        public var complex: String?
        /// Borough: M, Bx, Bk, Q, SI
        public var borough: String?
        /// Signage direction names northbound (N) and southbound (S), e.g. "Uptown" / "Downtown"
        public var northLabel: String?
        public var southLabel: String?

        public var coordinate: Coordinate { Coordinate(latitude: lat, longitude: lon) }

        public init(id: String, name: String, lat: Double, lon: Double, routes: [RouteDirections],
                    complex: String? = nil, borough: String? = nil,
                    northLabel: String? = nil, southLabel: String? = nil) {
            self.id = id
            self.name = name
            self.lat = lat
            self.lon = lon
            self.routes = routes
            self.complex = complex
            self.borough = borough
            self.northLabel = northLabel
            self.southLabel = southLabel
        }
    }

    private struct Document: Codable {
        var source: String
        var feedVersion: String
        var feedStartDate: String
        var feedEndDate: String
        var stations: [Entry]
    }

    public let source: String
    public let feedVersion: String
    public let entries: [Entry]
    private let byID: [String: Entry]

    /// Default entry time (seconds). Static GTFS has no per-station entry time, so a uniform estimate is used,
    /// and the UI notes "walking times are estimates".
    public static let defaultEntranceToPlatformSeconds: TimeInterval = 90

    public init(entries: [Entry], source: String = "", feedVersion: String = "") {
        self.entries = entries
        self.source = source
        self.feedVersion = feedVersion
        var map: [String: Entry] = [:]
        for e in entries { map[e.id] = e }
        self.byID = map
    }

    public static func decode(_ data: Data) throws -> StationCatalog {
        let doc = try JSONDecoder().decode(Document.self, from: data)
        return StationCatalog(entries: doc.stations, source: doc.source, feedVersion: doc.feedVersion)
    }

    /// Read the built-in station data.
    public static func loadBundled() throws -> StationCatalog {
        guard let url = Bundle.module.url(forResource: "subway_stations", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try decode(Data(contentsOf: url))
    }

    public func entry(id: String) -> Entry? { byID[id] }

    /// Where the monthly rebuild takes stop groups, boroughs and signage labels from (GTFS doesn't have them, see SubwayStaticBuilder):
    /// the app's own list first, so labels an app update fixes or adds reach a Mac that already has downloaded data,
    /// then the list in use for stations the app's list doesn't have.
    public static func labelSource(current: StationCatalog?) -> StationCatalog? {
        guard let bundled = try? loadBundled() else { return current }
        guard let current else { return bundled }
        let extra = current.entries.filter { bundled.entry(id: $0.id) == nil }
        return StationCatalog(entries: bundled.entries + extra, source: bundled.source, feedVersion: bundled.feedVersion)
    }

    /// Convert to the `Station` used by the decision module.
    public func station(id: String) -> Station? {
        guard let e = byID[id] else { return nil }
        return Station(id: e.id, name: e.name, coordinate: e.coordinate,
                       entrances: [], entranceToPlatformSeconds: Self.defaultEntranceToPlatformSeconds,
                       complexID: e.complex)
    }

    /// Stations within `radiusMeters` straight-line distance (for pre-filtering only), sorted by distance.
    public func stations(near coordinate: Coordinate, radiusMeters: Double) -> [Station] {
        entries
            .map { ($0, WalkEstimator.distanceMeters(coordinate, $0.coordinate)) }
            .filter { $0.1 <= radiusMeters }
            .sorted { $0.1 < $1.1 }
            .compactMap { station(id: $0.0.id) }
    }

    /// All routes through these stations (used to decide which live feeds to download).
    public func routes(atStations ids: [String]) -> Set<String> {
        var set = Set<String>()
        for id in ids {
            for r in byID[id]?.routes ?? [] { set.insert(MTARoute.normalize(r.route)) }
        }
        return set
    }

    /// For a station, route and direction: the signage direction name (e.g. "Uptown") and the terminal (e.g. "Woodlawn").
    /// The display name prefers the signage direction name; when the signage only says something vague like "Outbound", use "To <terminal>".
    /// - Parameter lastStationID: the last stop in this train's live data. When known, use it as the terminal (more accurate for branches and short runs).
    public func direction(stationID: String, route: String, code: String, lastStationID: String? = nil) -> Direction {
        let normalized = MTARoute.normalize(route)
        let entry = byID[stationID]
        let match = entry?.routes.first { MTARoute.normalize($0.route) == normalized }
        var terminal = code == "N" ? match?.north : match?.south
        if let lastStationID, lastStationID != stationID, let last = byID[lastStationID] {
            terminal = last.name
        }
        let fits = Self.labelExceptions[stationID + code]?.contains(normalized) != true
        let label = fits ? Self.meaningfulLabel(code == "N" ? entry?.northLabel : entry?.southLabel) : nil
        if let label {
            return Direction(code: code, name: label, terminal: terminal, label: label)
        }
        if let terminal {
            return Direction(code: code, name: "To \(terminal)", terminal: terminal)
        }
        return code == "N"
            ? Direction(code: "N", name: "Northbound")
            : Direction(code: "S", name: "Southbound")
    }

    /// Signage labels that are right for some routes at a station but not others: at Hoyt-Schermerhorn Sts, southbound "Queens" fits the A
    /// but not the C (to Euclid Av) or the G (to Church Av), which stay in Brooklyn; those use "To <terminal>" there.
    /// Kept here rather than in the station list, so the monthly rebuild doesn't lose it. Key: station ID + direction code.
    static let labelExceptions: [String: Set<String>] = ["A42S": ["C", "G"]]

    /// These signage wordings don't tell where the train is going, so the UI uses the terminal instead.
    /// ("Last Stop" means trains in this direction end here; a few stations are flipped in the official table, so it isn't used directly either.)
    static let genericLabels: Set<String> = [
        "Outbound", "Inbound", "Northbound", "Southbound", "Eastbound", "Westbound", "Last Stop",
    ]

    static func meaningfulLabel(_ label: String?) -> String? {
        guard let label = label?.trimmingCharacters(in: .whitespaces), !label.isEmpty,
              !genericLabels.contains(label) else { return nil }
        return label
    }

    /// Whether this route in this direction terminates at this station (trains go no further, so it can't be ridden).
    /// Determined from the most common terminal name in static GTFS, e.g. the 7 southbound terminates at 34 St-Hudson Yards.
    public func terminates(stationID: String, route: String, code: String) -> Bool {
        guard let entry = byID[stationID] else { return false }
        let normalized = MTARoute.normalize(route)
        guard let match = entry.routes.first(where: { MTARoute.normalize($0.route) == normalized }) else { return false }
        return (code == "N" ? match.north : match.south) == entry.name
    }
}

/// Route ID normalization.
public enum MTARoute {
    /// MTA uses "6X" "7X" "FX" for express service on the same route (diamond badge). For riders it's the same line, shown merged.
    public static func normalize(_ route: String) -> String {
        switch route {
        case "6X": return "6"
        case "7X": return "7"
        case "FX": return "F"
        default: return route
        }
    }

    /// Text shown on the route badge: all shuttles (GS, FS, H) show as S.
    public static func badge(_ route: String) -> String {
        switch route {
        case "GS", "FS", "H": return "S"
        case "SI": return "SIR"
        default: return normalize(route)
        }
    }
}
